DROP TABLE IF EXISTS `dcop_conf_bt`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dcop_conf_bt` (
  `tool_id` varchar(12) NOT NULL COMMENT 'length extend to 12 for sintering "before/after" omi -- 2020/03/18 lkchena',
  `recipe_id` varchar(32) NOT NULL,
  `active` int(11) NOT NULL,
  `itype` int(11) NOT NULL COMMENT 'default: 0 for dcop\n6000: ump shoulder measure\n6001: ump burr measure\n6010: 寬度計算\n6100: 肩高自動算,前兩欄值相減取絕對值\n610x: 肩高自動算,特殊欄位相減\n',
  `idxfield` int(11) NOT NULL,
  `field_type` int(11) NOT NULL DEFAULT 1 COMMENT '1: float 2: string , mapping n64,s10 fields ',
  `field_name` varchar(24) DEFAULT NULL,
  `field_desc` varchar(64) DEFAULT NULL,
  `iord` int(11) DEFAULT 1 COMMENT 'the filed order of report ',
  `usl` float DEFAULT NULL,
  `csl` float DEFAULT NULL,
  `lsl` float DEFAULT NULL,
  `value_on` float DEFAULT NULL,
  `value_off` float DEFAULT NULL,
  `value_def` float DEFAULT NULL,
  `xvalue1` float DEFAULT NULL,
  `xvalue2` float DEFAULT NULL,
  `xvalue3` float DEFAULT NULL,
  `decim` int(11) DEFAULT 0,
  `unit` varchar(8) DEFAULT NULL,
  `freq` int(11) NOT NULL DEFAULT -1 COMMENT 'data collect frequency: unit: second, -1: ignore(or event trigger)',
  `note` varchar(128) DEFAULT 'NULL',
  `rec_user` varchar(16) DEFAULT 'NULL',
  `rec_time` varchar(19) DEFAULT NULL,
  `node_id` varchar(16) DEFAULT NULL,
  `node_time` timestamp(6) NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`tool_id`,`recipe_id`,`active`,`itype`,`idxfield`,`field_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

